function activateModule(key) {
  const m = MODULES[key] || MODULES.junior;
  setActiveModuleKey(m.key);
  setModuleActiveVars(m.examKindFor, m.EXAM_PASS_MARKS, m.RARITY, m.CARD_CLASS, m.CARDS); BOSS_ART = m.BOSS_ART;
  TITLE_ART = m.TITLE_ART; UI_ART = m.UI_ART;
  setModuleSharedVars(m.TOPICS, m.DEEP_TOPICS, m.G); CONCEPTS = m.CONCEPTS;
  OLYMPIAD = m.OLYMPIAD; OLYMPIAD_PLAYBOOK = m.OLYMPIAD_PLAYBOOK; ACADEMY = m.ACADEMY;
  setBossesAndMaxLevel(m.BOSSES, m.MAX_LEVEL);
  EXAM_NAMES = m.EXAM_NAMES;
  setNamePools(m.NAMES_COMMON, m.NAMES_RARE, m.NAMES_EPIC, m.NAMES_LEGENDARY);
  MAX_STRENGTH_TOTAL = m.MAX_STRENGTH_TOTAL;
  setContentModule(key); // STORY/ADVENTURES/LESSONS live in kq-content.js
}

const cardById   = (id) => CARDS.find((c) => c.id === id);
const cardPower  = (c)  => c.s.reduce((a, b) => a + b, 0);
const cardTopStat = (c) => STAT_DEFS[c.s.indexOf(Math.max(...c.s))];

/* Pack odds scale with quest level: when a tier's gate opens it becomes the
   MOST likely drop, so progress never stalls waiting on a 3% pull. */
function packWeights(lv) {
  // Every tier is live from level 5 onward (post-chapter-4), so a lucky pull can surprise
  // a player early rather than epic/legendary being flatly impossible until level 7/9 — they
  // just start as a small chance and ramp up smoothly as level climbs. Common still dominates
  // the earliest levels so new/young players aren't overwhelmed by rare-looking cards immediately.
  if (lv <= 2) return { common: 100 };
  if (lv <= 4) return { common: 60, uncommon: 40 };
  if (lv <= 6) return { common: 40, uncommon: 28, rare: 20, epic: 8, legendary: 4 };
  if (lv <= 8) return { common: 26, uncommon: 24, rare: 24, epic: 18, legendary: 8 };
  return { common: 16, uncommon: 18, rare: 22, epic: 24, legendary: 20 };
}
function rollCardOnce(lv) {
  const w = packWeights(lv);
  const tiers = Object.keys(w).filter((t) => (RARITY[t].minLevel || 1) <= lv && w[t] > 0);
  const total = tiers.reduce((a, t) => a + w[t], 0);
  let roll = Math.random() * total, chosen = tiers[0], acc = 0;
  for (const t of tiers) { acc += w[t]; if (roll < acc) { chosen = t; break; } }
  const pool = CARDS.filter((c) => c.r === chosen);
  return pool[Math.floor(Math.random() * pool.length)];
}
function rollCard(unlockedLevel, ownedCards, forceRarity) {
  const lv = Math.min(Math.max(unlockedLevel || MAX_LEVEL, 1), MAX_LEVEL); // no arg = full pool (back-compat)
  // Pity override: force the roll into a specific rarity's pool (used for the epic/legendary
  // pity counters in openPack), still preferring an unowned card within that tier.
  if (forceRarity) {
    const pool = CARDS.filter((c) => c.r === forceRarity);
    let card = pool[Math.floor(Math.random() * pool.length)];
    if (ownedCards) { for (let t = 0; t < 4 && ownedCards[card.id]; t++) card = pool[Math.floor(Math.random() * pool.length)]; }
    return card;
  }
  let card = rollCardOnce(lv);
  // Duplicates add no strength, so keep rerolling (up to a few times) to try to land
  // an unowned card. This stops a player who has collected a whole tier from seeing
  // pack after pack of the same dupes; they get fresh cards from the eligible pool.
  if (ownedCards) { for (let t = 0; t < 4 && ownedCards[card.id]; t++) card = rollCardOnce(lv); }
  return card;
}

